import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

cpp_decl = r"""
#include <torch/extension.h>
torch::Tensor gemv_cute(torch::Tensor A, torch::Tensor B);
"""

cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>

#include <cute/tensor.hpp>

using namespace cute;

__device__ __forceinline__ float warp_reduce_sum(float v) {
  #pragma unroll
  for (int offset = 16; offset > 0; offset >>= 1)
    v += __shfl_down_sync(0xffffffffu, v, offset);
  return v;
}

__device__ __forceinline__ float dot4(const float4& a, const float4& b) {
  return fmaf(a.x, b.x, fmaf(a.y, b.y, fmaf(a.z, b.z, a.w * b.w)));
}

// C = A * B, with A:(M,K) row-major, B:(K,1), C:(M,1)
// K is huge, M is small -> memory-bandwidth bound reduction over K.
// Each block handles RowsPerBlock rows so that the B vector loads are
// reused across rows from registers, and every thread streams coalesced
// 128-bit (float4) loads of A.
template <int Threads, int RowsPerBlock, int Unroll>
__global__ void __launch_bounds__(Threads)
gemv_cute_kernel(const float* __restrict__ A,
                 const float* __restrict__ B,
                 float* __restrict__ C,
                 int M, int K)
{
  const int tid = threadIdx.x;
  const int m0  = blockIdx.x * RowsPerBlock;
  const int K4  = K >> 2;   // number of float4 elements per row

  // Global tensors (CuTe). A viewed as (M, K4) of float4, row stride = K4.
  Tensor gA = make_tensor(make_gmem_ptr(reinterpret_cast<const float4*>(A)),
                          make_shape(M, K4),
                          make_stride(K4, Int<1>{}));
  Tensor gB = make_tensor(make_gmem_ptr(reinterpret_cast<const float4*>(B)),
                          make_shape(K4),
                          make_stride(Int<1>{}));

  // Clamp row indices so loads are always in-bounds; stores are guarded.
  int rows[RowsPerBlock];
  #pragma unroll
  for (int r = 0; r < RowsPerBlock; ++r) {
    int m = m0 + r;
    rows[r] = (m < M) ? m : (M - 1);
  }

  float acc[RowsPerBlock][Unroll];
  #pragma unroll
  for (int r = 0; r < RowsPerBlock; ++r)
    #pragma unroll
    for (int u = 0; u < Unroll; ++u) acc[r][u] = 0.0f;

  int idx = tid;

  // Main loop: Unroll independent 128-bit loads per row per iteration,
  // fully coalesced across the warp at every step.
  for (; idx + (Unroll - 1) * Threads < K4; idx += Unroll * Threads) {
    float4 bv[Unroll];
    #pragma unroll
    for (int u = 0; u < Unroll; ++u) bv[u] = gB(idx + u * Threads);

    #pragma unroll
    for (int r = 0; r < RowsPerBlock; ++r) {
      #pragma unroll
      for (int u = 0; u < Unroll; ++u) {
        float4 av = gA(rows[r], idx + u * Threads);
        acc[r][u] += dot4(av, bv[u]);
      }
    }
  }

  // Tail over remaining float4 vectors.
  for (; idx < K4; idx += Threads) {
    float4 bv = gB(idx);
    #pragma unroll
    for (int r = 0; r < RowsPerBlock; ++r) {
      float4 av = gA(rows[r], idx);
      acc[r][0] += dot4(av, bv);
    }
  }

  // Block-level reduction per row.
  constexpr int NumWarps = Threads / 32;
  __shared__ float sdata[RowsPerBlock][NumWarps];

  const int lane = tid & 31;
  const int warp = tid >> 5;

  #pragma unroll
  for (int r = 0; r < RowsPerBlock; ++r) {
    float s = acc[r][0];
    #pragma unroll
    for (int u = 1; u < Unroll; ++u) s += acc[r][u];
    s = warp_reduce_sum(s);
    if (lane == 0) sdata[r][warp] = s;
  }
  __syncthreads();

  if (tid < 32) {
    #pragma unroll
    for (int r = 0; r < RowsPerBlock; ++r) {
      float v = (tid < NumWarps) ? sdata[r][tid] : 0.0f;
      v = warp_reduce_sum(v);
      if (tid == 0) {
        int m = m0 + r;
        if (m < M) C[m] = v;
      }
    }
  }
}

torch::Tensor gemv_cute(torch::Tensor A, torch::Tensor B) {
  TORCH_CHECK(A.is_cuda() && B.is_cuda(), "A and B must be CUDA tensors");
  TORCH_CHECK(A.scalar_type() == at::kFloat && B.scalar_type() == at::kFloat,
              "A and B must be float32");
  TORCH_CHECK(A.dim() == 2, "A must be 2D (M, K)");
  TORCH_CHECK(B.dim() == 2 && B.size(1) == 1, "B must be 2D (K, 1)");

  auto A_c = A.contiguous();
  auto B_c = B.contiguous();

  const int64_t M = A_c.size(0);
  const int64_t K = A_c.size(1);
  TORCH_CHECK(B_c.size(0) == K, "B.size(0) must equal A.size(1)");
  TORCH_CHECK(K % 4 == 0, "K must be divisible by 4 for vectorized loads");

  auto C = torch::empty({M, 1}, A_c.options());
  if (M == 0) return C;

  constexpr int Threads      = 256;
  constexpr int RowsPerBlock = 2;
  constexpr int Unroll       = 4;

  dim3 block(Threads);
  dim3 grid((unsigned)((M + RowsPerBlock - 1) / RowsPerBlock));

  cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();
  gemv_cute_kernel<Threads, RowsPerBlock, Unroll><<<grid, block, 0, stream>>>(
      A_c.data_ptr<float>(), B_c.data_ptr<float>(), C.data_ptr<float>(),
      (int)M, (int)K);

  auto err = cudaGetLastError();
  TORCH_CHECK(err == cudaSuccess, "gemv_cute launch failed: ",
              cudaGetErrorString(err));

  return C;
}
"""

gemv_ext = load_inline(
    name="gemv_cute_inline",
    cpp_sources=cpp_decl,
    cuda_sources=cuda_src,
    functions=["gemv_cute"],
    extra_cflags=["-O3"],
    extra_cuda_cflags=["-O3"],
    extra_include_paths=[
        "/home/tarasaba/PycharmProjects/cutegen_test/cutegen/cutlass/include",
        "/home/tarasaba/PycharmProjects/cutegen_test/cutegen/cutlass/include/cute/",
    ],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    Matrix-vector multiplication (C = A * B) implemented with a single
    custom CUDA kernel written with CuTe.
    """
    def __init__(self):
        super(ModelNew, self).__init__()
        self._ext = gemv_ext

    def forward(self, A: torch.Tensor, B: torch.Tensor) -> torch.Tensor:
        return self._ext.gemv_cute(A, B)

